package installstate

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
)

// BundleSHA256 hashes every file, including generated files, for exact bundle integrity.
func BundleSHA256(root string) (string, error) {
	return bundleSHA256(root, nil)
}

// BuiltinBundleSHA256 checks bundled sources without Python bytecode generated by
// normal helper imports. All other files still participate, preserving user edits.
func BuiltinBundleSHA256(root string) (string, error) {
	return bundleSHA256(root, func(entry os.DirEntry) bool {
		if entry.IsDir() {
			return entry.Name() == "__pycache__"
		}
		ext := filepath.Ext(entry.Name())
		return ext == ".pyc" || ext == ".pyo"
	})
}

func bundleSHA256(root string, skip func(os.DirEntry) bool) (string, error) {
	hasher := sha256.New()
	err := filepath.WalkDir(root, func(path string, d os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if path != root && skip != nil && skip(d) {
			if d.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if d.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if _, err := hasher.Write([]byte(rel)); err != nil {
			return err
		}
		if _, err := hasher.Write([]byte{0}); err != nil {
			return err
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		if _, err := hasher.Write(data); err != nil {
			return err
		}
		return nil
	})
	if err != nil {
		return "", fmt.Errorf("hash skill bundle: %w", err)
	}
	return hex.EncodeToString(hasher.Sum(nil)), nil
}
